// 按左端点升序后，能合并的区间一定相邻，只和当前这一段的右端点比较。
// LC 56：next[0] <= right（含相接）就合并，右端点取两者的较大值。
// 换题时若端点相接不算重叠，把 <= 改成 <。
static int[][] mergeIntervals(int[][] intervals) {
    if (intervals.length == 0) return new int[0][];
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    List<int[]> merged = new ArrayList<>();
    int left = intervals[0][0];
    int right = intervals[0][1];
    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] <= right) {
            right = Math.max(right, intervals[i][1]);
        } else {
            merged.add(new int[]{left, right});
            left = intervals[i][0];
            right = intervals[i][1];
        }
    }
    merged.add(new int[]{left, right});
    return merged.toArray(new int[0][]);
}

// 每段拆成开始 +1、结束 -1。按时间升序；时间相同先处理 -1，表示该时刻先释放。
// 答案是扫描过程中的最大累加值，不是合并后的段数。
// 换题时若闭区间在端点上仍算冲突，时间相同时让 +1 排在 -1 前面。
static int minMeetingRooms(int[][] intervals) {
    int n = intervals.length;
    int[][] events = new int[n * 2][2];
    for (int i = 0; i < n; i++) {
        events[2 * i][0] = intervals[i][0];
        events[2 * i][1] = 1;
        events[2 * i + 1][0] = intervals[i][1];
        events[2 * i + 1][1] = -1;
    }
    Arrays.sort(events, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
    int using = 0;
    int ans = 0;
    for (int[] event : events) {
        using += event[1];
        if (using > ans) ans = using;
    }
    return ans;
}

// nums[i] 表示从 i 最远到达 i + nums[i]。maxReach 只由已经可达的下标更新。
// 问能否到达时用 canJump：i 已经超过 maxReach 则失败。
static boolean canJump(int[] nums) {
    int maxReach = 0;
    int last = nums.length - 1;
    for (int i = 0; i <= last; i++) {
        if (i > maxReach) return false;
        int reach = i + nums[i];
        if (reach > maxReach) maxReach = reach;
        if (maxReach >= last) return true;
    }
    return true;
}

// LC 45 保证能到最后一个下标。end 是当前这一跳的右边界，farthest 是这一层能看到的更远位置。
// 走到 end 才算一次跳跃，并把 end 扩到 farthest。循环停在倒数第二个下标，最后一跳不另计。
// 换题若不能保证可达，当 farthest < i 时返回 -1。
static int jump(int[] nums) {
    int jumps = 0;
    int end = 0;
    int farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        int reach = i + nums[i];
        if (reach > farthest) farthest = reach;
        if (i == end) {
            jumps++;
            end = farthest;
        }
    }
    return jumps;
}

