import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int[][] merge(int[][] intervals) {
        // 起点有序后，新区间只可能和结果中的最后一段重叠。
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        List<int[]> merged = new ArrayList<>();

        for (int[] interval : intervals) {
            if (merged.isEmpty() || interval[0] > merged.get(merged.size() - 1)[1]) {
                // 起点落在最后一段右端点之后，两者分离，另开一段。
                merged.add(new int[]{interval[0], interval[1]});
            } else {
                // 有重叠时左端点不用改，把右端点拉到更远即可。
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], interval[1]);
            }
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

import java.util.*;

class Solution {
    public int[][] keepUncoveredIntervals(int[][] intervals) {
        // 左端点升序；同左端点时右端点更大的排在前面，才能先挡住后面的短区间。
        Arrays.sort(intervals, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(b[1], a[1]);
        });

        List<int[]> answer = new ArrayList<>();
        long maxRight = Long.MIN_VALUE;

        // 排序后只留这一个 for，同时处理“被前面包含”和“完全重复”。
        for (int i = 0; i < intervals.length; i++) {
            int left = intervals[i][0];
            int right = intervals[i][1];

            // 右端点没有超过此前最大右端点，说明已被前面某个区间包含。
            boolean coveredByPrevious = right <= maxRight;

            // 完全相同的下一格也会包含当前区间，所以重复的第一份也不能留。
            boolean duplicateLater = i + 1 < intervals.length
                    && intervals[i + 1][0] == left
                    && intervals[i + 1][1] == right;

            if (!coveredByPrevious && !duplicateLater) {
                answer.add(new int[]{left, right});
            }

            maxRight = Math.max(maxRight, right);
        }

        return answer.toArray(new int[answer.size()][]);
    }
}

import java.util.*;

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        if (intervals == null || intervals.length == 0) return 0;

        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));
        PriorityQueue<Integer> endTimes = new PriorityQueue<>();
        int answer = 0;

        for (int[] meeting : intervals) {
            // 堆顶是最早结束的房间，不晚于当前开始时间就可以释放。
            while (!endTimes.isEmpty() && endTimes.peek() <= meeting[0]) {
                endTimes.poll();
            }

            endTimes.offer(meeting[1]);
            // 入堆后的大小就是这一时刻同时占用的会议室数。
            answer = Math.max(answer, endTimes.size());
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public List<String> summaryRanges(int[] nums) {
        List<String> answer = new ArrayList<>();
        if (nums.length == 0) return answer;

        int start = 0;

        for (int i = 0; i < nums.length; i++) {
            // 用 long 相减，避免相邻元素相减在整数边界溢出，误判是否连续。
            boolean endOfRange = i == nums.length - 1
                    || (long) nums[i + 1] - nums[i] != 1L;

            if (endOfRange) {
                if (start == i) {
                    answer.add(String.valueOf(nums[i]));
                } else {
                    answer.add(nums[start] + "->" + nums[i]);
                }
                start = i + 1;
            }
        }

        return answer;
    }
}

class Solution {
    public int balancedStringSplit(String s) {
        int balance = 0;
        int answer = 0;

        for (char ch : s.toCharArray()) {
            if (ch == 'R') {
                balance++;
            } else {
                balance--;
            }

            // 前缀 L、R 数量相同，可以切出一段平衡子串
            if (balance == 0) {
                answer++;
            }
        }

        return answer;
    }
}

import java.util.*; // 使用 ArrayList 收集各段长度

class Solution {
    public List<Integer> partitionLabels(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;
        }

        List<Integer> answer = new ArrayList<>();
        int start = 0;
        int end = 0;

        for (int i = 0; i < s.length(); i++) {
            // 已见字母的最后位置可能把当前段终点继续右推
            end = Math.max(end, last[s.charAt(i) - 'a']);

            if (i == end) {
                // 段内字母都不会出现在 end 右侧，可以切下这一段
                answer.add(end - start + 1);
                start = i + 1;
            }
        }
        return answer;
    }
}

import java.util.*; // 模板导入，本题只扫描 nums

class Solution {
    public boolean canJump(int[] nums) {
        int farthest = 0;

        for (int i = 0; i < nums.length; i++) {
            // i 超出目前能落到的最远下标，前面有断点
            if (i > farthest) return false;

            farthest = Math.max(farthest, i + nums[i]);

            // 最远边界已经盖住末尾，不必再扫
            if (farthest >= nums.length - 1) return true;
        }
        return true;
    }
}

import java.util.*; // 保留模板导入，本题计算不依赖集合

class Solution {
    public int jump(int[] nums) {
        int jumps = 0;
        int currentEnd = 0; // 当前跳跃次数刚好覆盖到的右端
        int farthest = 0;   // 本层内再跳一次能到达的最远下标

        // 末位不用起跳，扫到 length-2 即可
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);

            // 走到层末必须再跳一次，右端扩到本层最远
            if (i == currentEnd) {
                jumps++;
                currentEnd = farthest;
            }
        }
        return jumps;
    }
}

import java.util.*; // 模板导入，本题只扫描价格数组

class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE;
        int bestProfit = 0;

        for (int price : prices) {
            // 最低价只来自今天及以前，卖出一定不早于买入
            minPrice = Math.min(minPrice, price);

            // 今天按历史最低价卖出；差为 0 时利润保持非负
            bestProfit = Math.max(bestProfit, price - minPrice);
        }
        return bestProfit;
    }
}

class Solution {
    public int maximumSwap(int num) {
        char[] chars = String.valueOf(num).toCharArray();
        int[] last = new int[10];
        // 同一数字多次出现时，只保留最靠右的位置
        for (int i = 0; i < chars.length; i++) {
            last[chars[i] - '0'] = i;
        }
        for (int i = 0; i < chars.length; i++) {
            int cur = chars[i] - '0';
            // 优先换更大的数字，让高位增加最多
            for (int d = 9; d > cur; d--) {
                if (last[d] > i) {
                    char tmp = chars[i];
                    chars[i] = chars[last[d]];
                    chars[last[d]] = tmp;
                    return Integer.parseInt(new String(chars));
                }
            }
        }
        return num;
    }
}

import java.util.Arrays;

public class MaxNumberLessThanN {
    public int buildMaxLessThan(int n, int[] digits) {
        Arrays.sort(digits);
        char[] target = String.valueOf(n).toCharArray();

        // 从高位开始，前缀此时仍与 n 对齐
        String sameLength = build(target, digits, 0, false);
        if (sameLength != null) {
            return Integer.parseInt(sameLength);
        }

        // 同位数失败后，少一位且每位取最大，仍是能拼出的最大数
        if (target.length == 1) {
            return -1;
        }

        StringBuilder shorter = new StringBuilder();
        for (int i = 0; i < target.length - 1; i++) {
            shorter.append(digits[digits.length - 1]);
        }
        return Integer.parseInt(shorter.toString());
    }

    private String build(char[] target, int[] digits, int index, boolean alreadyLess) {
        // 全程贴着 n 走到头会得到 n 本身，必须丢掉
        if (index == target.length) {
            return alreadyLess ? "" : null;
        }

        int current = target[index] - '0';

        // 大的先试，第一次成功就是这一层的最大选择
        for (int i = digits.length - 1; i >= 0; i--) {
            int d = digits[i];

            // 前缀还没变小，这一位不能超过 n 的对应位
            if (!alreadyLess && d > current) {
                continue;
            }

            // 这一位已经更小，后面再取最大也不会超过 n
            if (alreadyLess || d < current) {
                StringBuilder ans = new StringBuilder();
                ans.append(d);
                for (int j = index + 1; j < target.length; j++) {
                    ans.append(digits[digits.length - 1]);
                }
                return ans.toString();
            }

            // 与目标位相同，还要靠后面的位把整个数压小
            String next = build(target, digits, index + 1, false);
            if (next != null) {
                return d + next;
            }
        }

        // 这一位所有候选都失败，交给上一层换更小的数字
        return null;
    }
}
